/* Self-tests for hashes.h:
 *  - GF(2^64) multiply (PMULL/PCLMUL path) against a bit-serial reference
 *  - Mersenne multiply against __int128 % p
 *  - XXH3_64bits sanity vectors from xxHash's cli/xsum_sanity_check.c
 *    (buffer generated by XSUM_fillTestBuffer: byteGen = PRIME32; byte = byteGen>>56; byteGen *= PRIME64)
 *  - MUM fold identity used in the notes: mum_add(~u, ~Q) == mum_add(u, Q) - 1 + carry
 * Build: clang++ -O3 -std=c++17 -march=native selftest.cpp -o selftest
 */
#include <cstdio>
#include <cstdlib>
#include "hashes.h"

static uint64_t gf64_ref(uint64_t a, uint64_t b) {
    uint64_t r = 0;
    for (int i = 0; i < 64; i++) {
        if ((b >> i) & 1) r ^= a;
        uint64_t top = a >> 63; a <<= 1; if (top) a ^= 27;   // x^64 = x^4+x^3+x+1
    }
    return r;
}

int main() {
    int fails = 0;
    Rng r(42);
    for (int i = 0; i < 200000; i++) {
        uint64_t a = r.next(), b = r.next();
        if (i < 4) { a &= 0xff; }
        if (gf64_mul(a, b) != gf64_ref(a, b)) { if (fails++ < 5) printf("GF64 mismatch a=%016llx b=%016llx\n", (unsigned long long)a, (unsigned long long)b); }
        uint64_t x = r.next() % MERS_P, y = r.next() % MERS_P;
        uint64_t ref = (uint64_t)(((u128)x * y) % MERS_P);
        if (mers_mul(x, y) != ref) { if (fails++ < 5) printf("Mersenne mismatch\n"); }
    }
    // associativity/commutativity spot check of GF(2^64)
    for (int i = 0; i < 1000; i++) {
        uint64_t a = r.next(), b = r.next(), c = r.next();
        if (gf64_mul(gf64_mul(a, b), c) != gf64_mul(a, gf64_mul(b, c))) { fails++; printf("GF64 assoc fail\n"); }
    }
    // XXH3 sanity vectors
    uint8_t buf[256]; uint64_t byteGen = 2654435761ULL;
    for (int i = 0; i < 256; i++) { buf[i] = (uint8_t)(byteGen >> 56); byteGen *= 11400714785074694797ULL; }
    struct V { size_t len; uint64_t seed, expect; } vs[] = {
        {12, 0, 0xA713DAF0DFBB77E7ULL}, {12, 11400714785074694797ULL, 0xE7303E1B2336DE0EULL},
        {24, 0, 0xA3FE70BF9D3510EBULL}, {24, 11400714785074694797ULL, 0x850E80FC35BDD690ULL},
        {48, 0, 0x397DA259ECBA1F11ULL}, {48, 11400714785074694797ULL, 0xADC2CBAA44ACC616ULL},
        {80, 0, 0xBCDEFBBB2C47C90AULL}, {80, 11400714785074694797ULL, 0xC6DD0CB699532E73ULL},
        {195, 0, 0xCD94217EE362EC3AULL}, {195, 11400714785074694797ULL, 0xBA68003D370CB3D9ULL},
    };
    for (auto& v : vs) {
        uint64_t h = xxh3_64_ref(buf, v.len, v.seed);
        printf("XXH3 len=%zu seed=%llu: got %016llX expect %016llX %s\n", v.len, (unsigned long long)v.seed,
               (unsigned long long)h, (unsigned long long)v.expect, h == v.expect ? "OK" : "FAIL");
        if (h != v.expect) fails++;
    }
    // MUM add-fold complement identity: fold(~u,~Q) = fold(u,Q) - 1 + [lo(uQ) + u + Q + 1 >= 2^64]
    for (int i = 0; i < 1000000; i++) {
        uint64_t u = r.next(), q = r.next();
        u128 p = (u128)u * q; uint64_t L = (uint64_t)p;
        u128 s = (u128)L + u + q + 1; int c = (int)(s >> 64);
        uint64_t lhs = mum_add(~u, ~q), rhs = mum_add(u, q) - 1 + c;
        if (lhs != rhs) { if (fails++ < 5) printf("add-fold identity fail u=%016llx q=%016llx\n", (unsigned long long)u, (unsigned long long)q); }
    }
    // wyhash / rapidhash / mum: determinism + a printed vector for the record
    const char* s = "message digest";
    printf("wyhash(\"message digest\", seed 3, _wyp)  = %016llx\n", (unsigned long long)wyhash_ref(s, 14, 3, WYHASH_SECRET_DEFAULT));
    printf("rapidhash(\"message digest\", seed 3)     = %016llx\n", (unsigned long long)rapidhash_ref(s, 14, 3, RAPID_SECRET_DEFAULT));
    printf("mum_hash<8>(\"message digest\", seed 3)   = %016llx\n", (unsigned long long)mum_hash_ref<8>(s, 14, 3));
    printf("%s (%d failures)\n", fails ? "SELFTEST FAILED" : "SELFTEST PASSED", fails);
    return fails ? 1 : 0;
}
